const url = "https://science.nasa.gov/wp-json/wp/v2/apod-basic?per_page=1";

// The explanation arrives with HTML tags in it. This keeps only the words.
function cleanText(html) {
  const page = new DOMParser().parseFromString(html, "text/html");
  const words = page.body.textContent.split("Tomorrow's picture")[0];
  return words.replace("Explanation:", "").trim();
}

async function showToday() {
  const response = await fetch(url);      // ask NASA, wait for the reply
  const pictures = await response.json(); // turn JSON text into a list
  const today = pictures[0];              // the newest picture comes first

  document.querySelector("#title").textContent = today.title;
  document.querySelector("#photo").src = today.hdurl;
  document.querySelector("#photo").alt = today.alt;
  document.querySelector("#about").textContent = cleanText(today.explanation);
}

showToday();

function addCard(picture) {
  const card = document.createElement("article");
  card.className = "card";

  const photo = document.createElement("img");
  photo.src = picture.hdurl;
  photo.alt = picture.alt;      // NASA writes a description for screen readers
  photo.loading = "lazy";       // only download it when it nears the screen

  const title = document.createElement("h2");
  title.textContent = picture.title;

  card.append(photo, title);
  document.querySelector("#gallery").append(card);
}

async function loadGallery() {
  const status = document.querySelector("#status");
  try {
    const response = await fetch(url);
    // fetch only fails on a dead connection, so check the reply as well
    if (!response.ok) throw new Error(`NASA replied ${response.status}`);

    const pictures = await response.json();
    pictures.forEach(addCard);
    status.textContent = "";
  } catch (error) {
    console.error(error); // the details, for you, in the Console tab
    status.textContent = "Could not load pictures. Please try again later.";
  }
}

loadGallery();
